// src/helpers/prettyBytes.ts
function prettyBytes(n) {
  const UNITS = ["B", "KB", "MB", "GB", "TB", "PB", "EB", "ZB", "YB"];
  if (n < 1e3) {
    return n + " B";
  }
  const exponent = Math.min(Math.floor(Math.log10(n) / 3), UNITS.length - 1);
  n = Number((n / Math.pow(1e3, exponent)).toPrecision(3));
  const unit = UNITS[exponent];
  return n + " " + unit;
}

// src/podkop/fetchers/fetchServicesInfo.ts
async function fetchServicesInfo() {
  const [podkop, singbox] = await Promise.all([
    PodkopShellMethods.getStatus(),
    PodkopShellMethods.getSingBoxStatus()
  ]);
  if (!podkop.success || !singbox.success) {
    store.set({
      servicesInfoWidget: {
        loading: false,
        failed: true,
        data: { singbox: 0, podkop: 0 }
      }
    });
  }
  if (podkop.success && singbox.success) {
    store.set({
      servicesInfoWidget: {
        loading: false,
        failed: false,
        data: { singbox: singbox.data.running, podkop: podkop.data.enabled }
      }
    });
  }
}

// src/podkop/tabs/dashboard/helpers/statsWidgets.ts
function statsWidgets(current, previous) {
  if (!current?.running) {
    return {
      bandwidthWidget: {
        loading: false,
        failed: true,
        data: { up: 0, down: 0 }
      },
      trafficTotalWidget: {
        loading: false,
        failed: true,
        data: { downloadTotal: 0, uploadTotal: 0 }
      },
      systemInfoWidget: {
        loading: false,
        failed: true,
        data: { connections: 0, memory: 0 }
      }
    };
  }
  const widgets = {
    trafficTotalWidget: {
      loading: false,
      failed: false,
      data: { downloadTotal: current.down, uploadTotal: current.up }
    },
    systemInfoWidget: {
      loading: false,
      failed: false,
      data: { connections: current.connections, memory: current.memory }
    }
  };
  if (previous?.running) {
    const seconds = (current.at - previous.at) / 1e3;
    const rate = (now, before) => seconds > 0 && now >= before ? Math.round((now - before) / seconds) : 0;
    widgets.bandwidthWidget = {
      loading: false,
      failed: false,
      data: {
        up: rate(current.up, previous.up),
        down: rate(current.down, previous.down)
      }
    };
  }
  return widgets;
}

