async function onStoreUpdate(next, prev, diff) {
  if (diff.sectionsWidget) {
    renderSectionsWidget();
  }
  if (diff.bandwidthWidget) {
    renderBandwidthWidget();
  }
  if (diff.trafficTotalWidget) {
    renderTrafficTotalWidget();
  }
  if (diff.systemInfoWidget) {
    renderSystemInfoWidget();
  }
  if (diff.servicesInfoWidget) {
    renderServicesInfoWidget();
  }
}
var started = false;
var mounted = false;
var remounting = false;
async function onPageMount() {
  onPageUnmount();
  mounted = true;
  store.subscribe(onStoreUpdate);
  await fetchDashboardSections();
  await fetchServicesInfo();
  if (!mounted) return;
  startStats();
}
function onPageUnmount() {
  mounted = false;
  store.unsubscribe(onStoreUpdate);
  store.reset([
    "bandwidthWidget",
    "trafficTotalWidget",
    "systemInfoWidget",
    "servicesInfoWidget",
    "sectionsWidget"
  ]);
  stopStats();
}
function isCurrent() {
  return store.get().tabService.current === "dashboard";
}
async function initController() {
  if (started) {
    if (mounted && !remounting) {
      remounting = true;
      onMount(
        "dashboard-status",
        document.getElementById("dashboard-status")
      ).then(() => {
        remounting = false;
        if (mounted) onPageMount();
      });
    }
    return;
  }
  started = true;
  store.subscribe((next, prev, diff) => {
    if (!diff.tabService || next.tabService.current === prev.tabService.current) {
      return;
    }
    logger.debug("[DASHBOARD]", "active tab:", next.tabService.current);
    if (isCurrent()) {
      onMount("dashboard-status").then(() => {
        if (isCurrent() && !mounted) onPageMount();
      });
    } else if (mounted) {
      onPageUnmount();
    }
  });
  onMount("dashboard-status").then(() => {
    if (isCurrent() && !mounted) onPageMount();
  });
}

