// src/podkop/tabs/diagnostic/checks/runSectionsCheck.ts
async function runSectionsCheck() {
  const { order, title, code } = DIAGNOSTICS_CHECKS_MAP.OUTBOUNDS;
  updateCheckStore({
    order,
    code,
    title,
    description: _("Checking, please wait"),
    state: "loading",
    items: []
  });
  const sections = await getDashboardSections();
  if (!sections.success) {
    updateCheckStore({
      order,
      code,
      title,
      description: _("Cannot receive checks result"),
      state: "error",
      items: []
    });
    throw new Error("Sections checks failed");
  }
  const items = await Promise.all(
    sections.data.map(async (section) => {
      async function getLatency() {
        if (section.withTagSelect) {
          const latencyGroup = await PodkopShellMethods.getClashApiGroupLatency(
            section.code
          );
          const selectedOutbound = section.outbounds.find(
            (item) => item.selected
          );
          const isUrlTest = selectedOutbound?.type === "URLTest";
          const urlTestName = selectedOutbound?.displayName || _("Fastest");
          const success3 = latencyGroup.success && !latencyGroup.data.message;
          if (success3) {
            if (isUrlTest) {
              const delays = Object.values(latencyGroup.data).filter(
                (item) => typeof item === "number" && item > 0
              );
              if (!delays.length) {
                return {
                  success: false,
                  latency: `[${urlTestName}] ${_("Not responding")}`
                };
              }
              return {
                success: true,
                latency: `[${urlTestName}] ${delays.map((item) => `${item}ms`).join(" / ")}`
              };
            }
            const selectedProxyDelay = latencyGroup.data?.[selectedOutbound?.code ?? ""];
            if (selectedProxyDelay) {
              return {
                success: true,
                latency: `[${selectedOutbound?.displayName ?? ""}] ${selectedProxyDelay}ms`
              };
            }
            return {
              success: false,
              latency: `[${selectedOutbound?.displayName ?? ""}] ${_("Not responding")}`
            };
          }
          return {
            success: false,
            latency: _("Not responding")
          };
        }
        const latencyProxy = await PodkopShellMethods.getClashApiProxyLatency(
          section.code
        );
        const success2 = latencyProxy.success && !latencyProxy.data.message;
        if (success2) {
          return {
            success: true,
            latency: `${latencyProxy.data.delay} ms`
          };
        }
        return {
          success: false,
          latency: _("Not responding")
        };
      }
      const { latency, success } = await getLatency();
      return {
        state: success ? "success" : "error",
        key: section.displayName,
        value: latency
      };
    })
  );
  const direct = await PodkopShellMethods.getClashApiProxyLatency("direct-out");
  const directWorks = direct.success && !direct.data.message;
  items.push({
    state: directWorks ? "success" : "error",
    key: _("Direct (without a proxy)"),
    value: directWorks ? `${direct.data.delay} ms` : _("Not responding")
  });
  const allGood = items.every((item) => item.state === "success");
  const atLeastOneGood = items.some((item) => item.state === "success");
  const { state, description } = getMeta({ atLeastOneGood, allGood });
  updateCheckStore({
    order,
    code,
    title,
    description,
    state,
    items
  });
  if (!atLeastOneGood) {
    throw new Error("Sections checks failed");
  }
}

// src/helpers/removeVersionPrefix.ts
function removeVersionPrefix(version) {
  return version.replace(/^v/, "");
}

// src/podkop/tabs/diagnostic/helpers/getPodkopVersionRow.ts
function isUnknownVersion(version) {
  return version === "unknown" || version === _("unknown");
}
function getPodkopVersionRow(diagnosticsSystemInfo) {
  const loading = diagnosticsSystemInfo.loading;
  const unknown = isUnknownVersion(diagnosticsSystemInfo.podkop_version);
  const hasActualVersion = Boolean(diagnosticsSystemInfo.podkop_latest_version) && !isUnknownVersion(diagnosticsSystemInfo.podkop_latest_version);
  const version = normalizeCompiledVersion(
    diagnosticsSystemInfo.podkop_version
  );
  const isDevVersion = version === "dev";
  if (loading || unknown || !hasActualVersion || isDevVersion) {
    return {
      key: "Podkop",
      value: version
    };
  }
  if (removeVersionPrefix(version) !== removeVersionPrefix(diagnosticsSystemInfo.podkop_latest_version)) {
    return {
      key: "Podkop",
      value: version,
      tag: {
        label: _("Outdated"),
        kind: "warning"
      }
    };
  }
  return {
    key: "Podkop",
    value: version,
    tag: {
      label: _("Latest"),
      kind: "success"
    }
  };
}

// src/helpers/getLatestRelease.ts
var RELEASE_URL = "https://api.github.com/repos/podkop-net/podkop-experimental/releases/latest";
var CACHE_KEY = "podkop-latest-release";
var CACHE_MS = 60 * 60 * 1e3;
var FAILURE_MS = 10 * 60 * 1e3;
function readCachedRelease(now, raw) {
  if (!raw) return void 0;
  try {
    const cached = JSON.parse(raw);
    if (typeof cached.tag !== "string" || typeof cached.at !== "number") {
      return void 0;
    }
    if (now - cached.at < (cached.tag ? CACHE_MS : FAILURE_MS)) {
      return cached.tag;
    }
  } catch {
  }
  return void 0;
}
function keep(tag) {
  try {
    localStorage.setItem(CACHE_KEY, JSON.stringify({ tag, at: Date.now() }));
  } catch {
  }
}
async function ask() {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 5e3);
  try {
    const response = await fetch(RELEASE_URL, { signal: controller.signal });
    if (!response.ok) return "";
    const tag = (await response.json()).tag_name;
    return typeof tag === "string" ? tag : "";
  } catch {
    return "";
  } finally {
    clearTimeout(timer);
  }
}
async function getLatestRelease() {
  let stored = null;
  try {
    stored = localStorage.getItem(CACHE_KEY);
  } catch {
  }
  const cached = readCachedRelease(Date.now(), stored);
  if (cached !== void 0) return cached;
  const tag = await ask();
  keep(tag);
  return tag;
}

